        "George": "C",
        "Shunichi": "C",
        "Mio": "C"
      },
      "adopted": "C",
      "turns": [
        {
          "turn": 1,
          "lines": {
            "Asuka": "Argues for the option that maximizes space and removes ownership.",
            "Ryuji": "Argues for the option that generates revenue and reflects usage value.",
            "George": "Supports the option that ensures everyone gets a fair turn over time.",
            "Shunichi": "Supports the option that is impartial and avoids financial conflict.",
            "Mio": "Supports the option that requires the least amount of monthly paperwork."
          }
        },
        {
          "turn": 2,
          "lines": {
            "Asuka": "Points out that the hardware for the shared option is too difficult to use.",
            "Ryuji": "Notes that the lottery doesn't solve the issue of daily riders needing priority.",
            "George": "Argues that a lottery is the most traditional and accepted way to handle scarcity.",
            "Shunichi": "Agrees that a lottery prevents the 'rich' or 'loud' from dominating.",
            "Mio": "Confirms that a yearly event is easier to manage than monthly billing."
          }
        },
        {
          "turn": 3,
          "lines": {
            "Asuka": "Admits the shared racks might be too physically demanding for some.",
            "Ryuji": "Accepts that the social risk of payment might be too high for this building.",
            "George": "Urges the group to vote for the most equitable rotation.",
            "Shunichi": "Reminds them that a clear, random rule prevents personal grudges.",
            "Mio": "Agrees that the lottery is the most sustainable choice."
          }
        },
        {
          "turn": 4,
          "lines": {
            "Asuka": "Over",
            "Ryuji": "Over",
            "George": "Over",
            "Shunichi": "Over",
            "Mio": "Over"
          }
        }
      ]
    }
  ],
  "seats": {
    "Ryuji": "Cares about the financial reality and cost-benefit. He pushes for a value-based system but yields when social harmony is prioritized.",
    "Mio": "Cares about the administrative workload and physical ease of use. She rejects complex or high-maintenance systems.",
    "Asuka": "Cares about the physical organization and efficiency of the space. She initially wants a high-density solution but worries about usability.",
    "George": "Cares about fairness and the removal of long-term unfair advantages. He advocates for a system that rotates access.",
    "Shunichi": "Cares about maintaining positive social dynamics and avoiding conflict. He opposes any system that introduces financial tension."
  },
  "final": {
    "adopted": "C"
  }
}
